// Check an approved fix before anything touches Cloudflare. Only creating or
// updating one A, AAAA, CNAME, MX or TXT record inside the incident's own domain
// is allowed. Deletions, nameservers and registrar changes always stay manual.
const input = $input.first().json;
const domain = String(input.domain ?? '').trim().toLowerCase().replace(/\.$/, '');
const ids = { approval_id: input.approval_id ?? '', incident_id: input.incident_id ?? '' };
const fail = (message) => [{ json: { ok: false, message, domain, ...ids } }];

let fix;
try {
  fix = typeof input.fix === 'string' ? JSON.parse(input.fix) : input.fix;
} catch (e) {
  return fail('The fix is not valid JSON.');
}
if (!fix || typeof fix !== 'object') return fail('No fix was attached to this approval.');

const action = String(fix.action ?? '').trim().toLowerCase();
const type = String(fix.type ?? '').trim().toUpperCase();
const name = String(fix.name ?? '').trim().toLowerCase().replace(/\.$/, '');
const content = String(fix.content ?? '').trim();
if (!['create', 'update'].includes(action)) return fail('Only "create" and "update" can be applied automatically; "' + action + '" has to be done by hand.');
if (!['A', 'AAAA', 'CNAME', 'MX', 'TXT'].includes(type)) return fail(type + ' records have to be changed by hand.');
if (!domain || !(name === domain || name.endsWith('.' + domain))) return fail('The record ' + name + ' is outside ' + domain + '.');
if (!content || content.length > 2048) return fail('The new record value is missing or too long.');
if (type === 'MX' && !Number.isInteger(Number(fix.priority))) return fail('An MX record needs a numeric priority.');

const record = { type, name, content, ttl: Number.isInteger(Number(fix.ttl)) && Number(fix.ttl) >= 60 ? Number(fix.ttl) : 1 };
if (type === 'MX') record.priority = Number(fix.priority);
if (['A', 'AAAA', 'CNAME'].includes(type) && typeof fix.proxied === 'boolean') record.proxied = fix.proxied;
const oldContent = fix.old_content == null ? null : String(fix.old_content).trim();
return [{ json: { ok: true, domain, action, record, old_content: oldContent, ...ids } }];

// Decide the exact Cloudflare call from what is there now. Nothing is written
// when the record already has the new value, or when an update is ambiguous.
const v = $('Validate fix').first().json;
const zoneRes = $('Find zone').first().json;
const recRes = $input.first().json;
const r = v.record;
const bare = (s) => String(s ?? '').replace(/^"|"$/g, '');
const show = (x) => (x.type === 'MX' ? x.priority + ' ' : '') + bare(x.content);
const errorOf = (res) => {
  if (res.error) return typeof res.error === 'string' ? res.error : (res.error.message || JSON.stringify(res.error));
  if (res.success === false) return (res.errors || []).map(e => e.message).join('; ') || 'unknown error';
  return null;
};
const stop = (result, message, extra = {}) => [{ json: { ...v, write: false, result, message, ...extra } }];

const zoneError = errorOf(zoneRes);
if (zoneError) return stop('failed', 'Cloudflare zone lookup failed: ' + zoneError);
const zone = (zoneRes.result || [])[0];
if (!zone) return stop('failed', v.domain + ' is not in the connected Cloudflare account.');
const recError = errorOf(recRes);
if (recError) return stop('failed', 'Cloudflare record lookup failed: ' + recError);

const existing = (recRes.result || []).filter(x => x.type === r.type && x.name.toLowerCase() === r.name);
const before = existing.map(show).join(' | ');
if (existing.some(x => bare(x.content) === bare(r.content) && (r.type !== 'MX' || x.priority === r.priority))) {
  return stop('already_present', 'Cloudflare already has this value, so nothing was changed.', { zone_id: zone.id, before });
}
const url = 'https://api.cloudflare.com/client/v4/zones/' + zone.id + '/dns_records';
if (v.action === 'create') {
  return [{ json: { ...v, write: true, method: 'POST', url, zone_id: zone.id, before, undo: 'Delete the ' + r.type + ' record ' + r.name + ' = ' + show(r) + ' in Cloudflare.' } }];
}
const targets = v.old_content ? existing.filter(x => bare(x.content) === bare(v.old_content)) : existing;
if (targets.length === 0) return stop('failed', 'There is no existing ' + r.type + ' record ' + r.name + (v.old_content ? ' with that old value' : '') + ' to update.', { before });
if (targets.length > 1) return stop('failed', 'Several ' + r.type + ' records match ' + r.name + ', so the update is ambiguous. It needs old_content or a manual change.', { before });
const t = targets[0];
return [{ json: { ...v, write: true, method: 'PATCH', url: url + '/' + t.id, zone_id: zone.id, record_id: t.id, before: show(t), undo: 'Set the ' + r.type + ' record ' + r.name + ' back to ' + show(t) + ' in Cloudflare.' } }];

// Combine whichever path ran into one row for the Changes tab and one result
// for the router.
const v = $('Validate fix').first().json;
let plan = null;
let write = null;
try { plan = $('Plan change').first().json; } catch (e) {}
try { write = $('Write record').first().json; } catch (e) {}
const show = (x) => x ? (x.type === 'MX' ? x.priority + ' ' : '') + String(x.content ?? '').replace(/^"|"$/g, '') : '';

let out;
if (!v.ok) out = { result: 'rejected', message: v.message };
else if (!plan || !plan.write) out = { result: plan?.result ?? 'failed', message: plan?.message ?? 'The fix could not be planned.' };
else {
  const err = write?.error
    ? (typeof write.error === 'string' ? write.error : (write.error.message || JSON.stringify(write.error)))
    : (write?.success === false ? (write.errors || []).map(e => e.message).join('; ') : null);
  out = err || !write
    ? { result: 'failed', message: 'Cloudflare did not accept the change: ' + (err || 'no response') }
    : { result: 'applied', message: (plan.method === 'POST' ? 'Created ' : 'Updated ') + plan.record.type + ' ' + plan.record.name + ' = ' + show(plan.record) + '.', record_id: write.result?.id ?? plan.record_id };
}
const p = plan ?? v;
return [{ json: {
  'Timestamp': new Date().toISOString(),
  'Approval ID': v.approval_id,
  'Incident ID': v.incident_id,
  'Zone': v.domain,
  'Action': v.action ?? '',
  'Type': v.record?.type ?? '',
  'Name': v.record?.name ?? '',
  'Before': p.before ?? '',
  'After': out.result === 'applied' ? show(v.record) : '',
  'Record ID': out.record_id ?? '',
  'Result': out.result,
  'Message': out.message,
  'Undo': out.result === 'applied' ? (plan.undo ?? '') : '',
  result: out.result,
  message: out.message,
} }];

// Hand the outcome back to the router.
const r = $('Build result').first().json;
return [{ json: { result: r.result, message: r.message, before: r['Before'], after: r['After'], undo: r['Undo'] } }];
